for(const kind of ['scalar','empty','collection','mixed'] as const)for(const outcome of ['confirm','rollback'] as const)it(`first omission ${kind}: undeclared child waits then delivers after ${outcome}`,async()=>{
 const tree=signalTree({branch:{rows:entityMap<{id:string;x:number},string>(),x:0},other:0},{enhancers:[transactions()]});
 const foreign=signalTree({z:0},{enhancers:[transactions()]});
 if(kind!=='empty')tree.$.branch.rows.addOne({id:'a',x:0});await flush();
 const sent:unknown[]=[],nestedSent:unknown[]=[];const c=asLink(tree.$,sent);
 const child=asLink(kind==='scalar'?tree.$.branch.x:kind==='mixed'?tree.$.branch:tree.$.branch.rows,nestedSent);
 const q=foreign.transact(()=>foreign.$.z(7));
 try{
  c.declare({kind:'dependent',owners:[q]},()=>kind==='scalar'?tree.$.branch.x(7):kind==='empty'?tree.$.branch.rows.addOne({id:'a',x:7}):tree.$.branch.rows.updateOne('a',{x:7}));
  await flush();expect(sent).toEqual([]);
  c.declare({kind:'independent'},()=>tree.$({other:1} as never));await flush();expect(sent).toEqual([{other:1}]);
  // A root declaration does not grant its undeclared child permission.
  expect(nestedSent).toEqual([]);
  q[outcome]();await flush();
  expect(sent).toEqual([{other:1}]);
  expect(nestedSent).toEqual([kind==='empty'||kind==='collection'?[]:undefined]);
 }finally{c.dispose();child.dispose();tree.destroy();foreign.destroy();}
});

for(const outcome of ['confirm','rollback'] as const)it(`equal undeclared recipient proof does not discard held useful revision: ${outcome}`,async()=>{
 const o=signalTree({z:0},{enhancers:[transactions()]});const t=signalTree({pair:{x:0,y:0}});const left:unknown[]=[],right:unknown[]=[];const a=link(t.$.pair,{set:v=>{left.push(v);}}) as Declared;const b=link(t.$.pair,{set:v=>{right.push(v);}});const p=o.transact(()=>o.$.z(7));
 try{a.declare({kind:'independent'},()=>t.$.pair({x:1,y:0}));await flush();const second=a.declare({kind:'independent'},()=>t.$.pair({x:1,y:0}));await flush();expect(second.read()).toMatchObject({state:'no-write'});expect(left).toEqual([{x:1,y:0}]);expect(right).toEqual([]);p[outcome]();await flush();expect(right).toEqual([{x:1,y:0}]);await b.settled();}finally{a.dispose();b.dispose();t.destroy();o.destroy();}
});

